    "stroke36": "السكتة الإقفارية: التحلل الوريدي (أدوية إذابة الجلطات مثل tPA) أو إزالة الجلطات الميكانيكية.",
    "stroke37": "السكتة النزفية: التدخلات الجراحية لوقف النزيف أو تخفيف الضغط في الدماغ.",
    "stroke38": "التأهيل: العلاج الطبيعي والمهني والنطقي لدعم التعافي.",
    "stroke39": "الأدوية: مميعات الدم أو مضادات التخثر أو أدوية ضغط الدم للوقاية من السكتات الدماغية المستقبلية.",
    "stroke40": "التدخلات الجراحية",
    "stroke41": "في بعض الحالات، يكون التدخل الجراحي ضروريًا لمعالجة السبب الأساسي للسكتة الدماغية. تشمل الإجراءات الشائعة:",
    "stroke42": "إزالة الجلطات الميكانيكية: إجراء يعتمد على القسطرة لإزالة جلطة في الأوعية الدموية الدماغية.",
    "stroke43": "استئصال باطنة الشريان السباتي: جراحة لإزالة الترسبات من الشرايين السباتية في الرقبة.",
    "stroke44": "كرانيكتومي: جراحة لتخفيف الضغط الناتج عن تورم الدماغ.",
    "stroke45": "ما الذي يمكن أن يتوقعه المريض",
    "stroke46": "تختلف تأثيرات السكتة الدماغية من مريض لآخر، بناءً على شدة السكتة وموقعها. تشمل التجارب الشائعة:",
    "stroke47": "ضعف أو شلل في جانب واحد من الجسم",
    "stroke48": "صعوبة في التحدث أو فهم اللغة",
    "stroke49": "تغيرات في المزاج أو العواطف، بما في ذلك الاكتئاب",
    "stroke50": "ضعف في الذاكرة أو القدرات الإدراكية",
    "stroke51": "تحديات في المهام اليومية، مثل الأكل أو المشي",
    "stroke52": "غالبًا ما يتضمن التعافي نهجًا متعدد التخصصات، بما في ذلك العلاج الطبيعي والدعم النفسي وتغيير نمط الحياة.",
    "stroke53": "العودة إلى الرئيسية",
    "venus1": "تجلط الأوردة",
    "venus2": "دليل متعمق لأسباب وأعراض وعلاجات التجلط الوريدي",
    "venus3": "رسم توضيحي لتجلط الأوردة",
    "venus4": "ما هو تجلط الأوردة؟",
    "venus5": "يشير تجلط الأوردة إلى تكوين جلطة دموية (خثرة) في الوريد. يمكن أن يحدث في الأوردة السطحية (التهاب الوريد الخثاري السطحي) أو الأوردة العميقة (تجلط الأوردة العميقة). يعد تجلط الأوردة العميقة الشكل الأكثر إثارة للقلق، حيث يمكن أن تتحرك الجلطة إلى الرئتين، مسببة حالة قاتلة تعرف باسم الانسداد الرئوي. الاكتشاف المبكر والعلاج أمران حاسمان لمنع المضاعفات الخطيرة.",
    "venus6": "السمات الرئيسية",
    "venus7": "تشكل جلطة دموية في الوريد مما يعيق تدفق الدم",
    "venus8": "يحدث غالبًا في الأوردة العميقة للساقين",
    "venus9": "يمكن أن يسبب مضاعفات مهددة للحياة مثل الانسداد الرئوي",
    "venus10": "يرتبط غالبًا بعدم الحركة لفترة طويلة أو الجراحة أو بعض الحالات الطبية",
    "venus11": "الأعراض",
    "venus12": "قد يتطور تجلط الأوردة بصمت، ولكن عند ظهور الأعراض، غالبًا ما تشمل:",
    "venus13": "تورم في الطرف المصاب",
    "venus14": "ألم أو حساسية في المنطقة المصابة، خاصة عند الوقوف أو المشي",
    "venus15": "احمرار أو تغير لون الجلد",
    "venus16": "دفء في المنطقة المصابة",
    "venus17": "ضيق مفاجئ في التنفس أو ألم في الصدر (إذا انتقلت الجلطة إلى الرئتين)",
    "venus18": "الأسباب وعوامل الخطر",
    "venus19": "يتطور تجلط الأوردة عندما يتباطأ تدفق الدم أو يصبح راكدًا، مما يؤدي إلى تكوين جلطة. تشمل الأسباب وعوامل الخطر الشائعة:",
    "venus20": "عدم الحركة لفترة طويلة: مثل الرحلات الجوية الطويلة أو الإقامة في المستشفى",
    "venus21": "الجراحة: خاصة العمليات الجراحية في العظام أو البطن",
    "venus22": "الإصابة: إصابة الأوعية الدموية",
    "venus23": "الحالات الطبية: السرطان، فشل القلب، أو الأمراض الالتهابية",
    "venus24": "التغيرات الهرمونية: الحمل، حبوب منع الحمل، أو العلاج بالهرمونات البديلة",
    "venus25": "العوامل الوراثية: اضطرابات التخثر الوراثية",
    "venus26": "السمنة: زيادة الضغط على الأوردة",
    "venus27": "خيارات العلاج",
    "venus28": "تهدف معالجة تجلط الأوردة إلى منع نمو الجلطة وتقليل الأعراض ومنع المضاعفات مثل الانسداد الرئوي. تشمل العلاجات الشائعة:",
    "venus29": "مضادات التخثر: أدوية تسييل الدم (مثل الهيبارين أو الوارفارين أو مضادات التخثر الفموية المباشرة) لمنع نمو الجلطة وتقليل خطر الجلطات الجديدة.",
    "venus30": "العلاج بالضغط: الجوارب الضاغطة لتحسين تدفق الدم وتقليل التورم.",
    "venus31": "إذابة الجلطة: في الحالات الشديدة، يتم إعطاء أدوية لإذابة الجلطة.",
    "venus32": "مرشح الوريد الأجوف السفلي (IVC): جهاز يتم وضعه في الوريد لمنع الجلطات من التحرك إلى الرئتين، ويستخدم للمرضى الذين لا يمكنهم تناول مضادات التخثر.",
    "venus33": "استراتيجيات الوقاية",
    "venus34": "تتضمن الوقاية من تجلط الأوردة معالجة عوامل الخطر وتعزيز تدفق الدم الصحي. تشمل الاستراتيجيات الرئيسية:",
    "venus35": "الحركة المنتظمة والتمارين، خاصة خلال فترات الجلوس الطويلة",
    "venus36": "الحفاظ على وزن صحي وتجنب الجلوس أو الوقوف لفترات طويلة",
    "venus37": "ارتداء الجوارب الضاغطة كما يوصي مقدم الرعاية الصحية",
    "venus38": "شرب الماء بكثرة للحفاظ على لزوجة الدم المثلى",
    "venus39": "استخدام مضادات التخثر قبل وبعد الجراحة حسب الوصفة",
    "venus40": "ماذا يتوقع المرضى",
    "venus41": "غالبًا ما يمر مرضى تجلط الأوردة بمجموعة من الأعراض والمشاعر اعتمادًا على شدة حالتهم. تشمل النتائج عادةً:",
    "venus42": "تخفيف الأعراض بالعلاج المناسب",
    "venus43": "تحسن في الحركة وتقليل التورم بعد العلاج",
    "venus44": "الاطمئنان بعد منع المضاعفات بنجاح",
    "venus45": "الالتزام بالمراقبة المستمرة وتعديلات نمط الحياة لمنع التكرار",
    "venus46": "تختلف أوقات التعافي، حيث يتم حل الحالات البسيطة في غضون أسابيع بينما تتطلب الحالات الأكثر خطورة شهورًا من العلاج بمضادات التخثر.",
    "venus47": "العودة إلى الصفحة الرئيسية",
