    "tumor3": "ما هو انصمام الورم؟",
    "tumor4": "انصمام الورم هو إجراء طفيف التوغل يستخدم لقطع إمدادات الدم عن الورم. تقلل هذه التقنية من حجم الورم وتحد من نموه عن طريق قطع الأكسجين والمغذيات اللازمة له. يتم إجراؤه غالبًا قبل الجراحة لتسهيل إزالة الورم أو كإجراء تلطيفي لتخفيف الأعراض.",
