    "tumor50": "العودة إلى الصفحة الرئيسية",
    "spinal1": "التشوه الشرياني الوريدي في العمود الفقري",
    "spinal2": "فهم التشوهات الشريانية الوريدية الشوكية",
    "spinal3": "رسم توضيحي للتشوه الشرياني الوريدي الشوكي",
    "spinal4": "ما هو التشوه الشرياني الوريدي الشوكي؟",
    "spinal5": "التشوه الشرياني الوريدي الشوكي (Spinal AVM) هو تشابك غير طبيعي للأوعية الدموية الموجودة داخل أو حول الحبل الشوكي. تعطل هذه التشوهات التدفق الطبيعي للدم بين الشرايين والأوردة، مما يؤدي إلى تقليل إمداد الأكسجين للحبل الشوكي. بمرور الوقت، قد يؤدي ذلك إلى تلف تدريجي أو أعراض عصبية مفاجئة إذا تمزق التشوه، مما يسبب نزيفًا (نزفًا).",
    "spinal6": "الاختلافات الرئيسية",
    "spinal7": "اتصال غير طبيعي بين الشرايين والأوردة في الحبل الشوكي",
    "spinal8": "قد يظل بدون أعراض لسنوات",
    "spinal9": "خطر مرتفع للنزيف، مما يسبب تلفًا عصبيًا",
    "spinal10": "غالبًا ما يتم تشخيصه باستخدام تقنيات التصوير المتقدمة مثل التصوير بالرنين المغناطيسي أو تصوير الأوعية",
    "spinal11": "الأعراض",
    "spinal12": "تعتمد أعراض التشوه الشرياني الوريدي الشوكي على حجمه وموقعه وما إذا كان قد تمزق. تشمل الأعراض الشائعة:",
    "spinal13": "ضعف تدريجي أو تنميل في الساقين",
    "spinal14": "ألم في الظهر أو عدم راحة موضعية",
    "spinal15": "فقدان التحكم في الأمعاء أو المثانة",
    "spinal16": "ظهور مفاجئ لألم شديد وشلل (في حالة حدوث تمزق)",
    "spinal17": "ضعف العضلات أو التشنج",
    "spinal18": "انخفاض الإحساس أو وخز في الأطراف",
    "spinal19": "الأسباب وعوامل الخطر",
    "spinal20": "السبب الدقيق للتشوهات الشريانية الوريدية الشوكية غير معروف غالبًا، ولكن يُعتقد أنها تنشأ أثناء تطور الجنين. تشمل بعض العوامل والحالات المرتبطة بالتشوهات الشريانية الوريدية الشوكية:",
    "spinal21": "عوامل خلقية: تشوهات موجودة عند الولادة",
    "spinal22": "اضطرابات وراثية: مثل توسع الشعيرات النزفي الوراثي (HHT)",
    "spinal23": "الإصابة: قد يساهم تلف الأوعية الدموية الشوكية في حالات نادرة",
    "spinal24": "العدوى: قد تسبب بعض العدوى تشوهات وعائية",
    "spinal25": "التشخيص",
    "spinal26": "يتضمن تشخيص التشوهات الشريانية الوريدية الشوكية مجموعة من التقييم السريري والدراسات التصويرية لتأكيد وجود الأوعية الدموية غير الطبيعية. تشمل أدوات التشخيص الشائعة:",
    "spinal27": "التصوير بالرنين المغناطيسي (MRI): يوفر صورًا تفصيلية للحبل الشوكي والأنسجة المحيطة",
    "spinal28": "تصوير الأوعية بالرنين المغناطيسي (MRA): يُستخدم لتصور تدفق الدم واكتشاف الشذوذ",
    "spinal29": "تصوير الأوعية الشوكية: إجراء يعتمد على القسطرة لرسم خريطة الأوعية الدموية في العمود الفقري",
    "spinal30": "خيارات العلاج",
    "spinal31": "يعتمد علاج التشوهات الشريانية الوريدية الشوكية على عوامل مثل أعراض المريض وحجم التشوه وموقعه وخطر التمزق. تشمل العلاجات الشائعة:",
    "spinal32": "التصليب: إجراء طفيف التوغل حيث يتم استخدام قسطرة لحقن مادة في التشوه لحجب تدفق الدم وتقليل حجمه.",
    "spinal33": "الاستئصال الجراحي: إزالة التشوه من خلال جراحة المجهر. غالبًا ما يُستخدم للأورام القابلة للوصول والأعراض.",
    "spinal34": "الجراحة الإشعاعية: إجراء غير جراحي يستخدم الإشعاع المركّز لإغلاق الأوعية غير الطبيعية بمرور الوقت.",
    "spinal35": "المراقبة: للتشوهات الصغيرة بدون أعراض، قد يوصي الأطباء بمراقبة الحالة من خلال التصوير المنتظم.",
    "spinal36": "ما يمكن أن يتوقعه المرضى",
    "spinal37": "قد يكون العيش مع التشوه الشرياني الوريدي الشوكي تحديًا، لكن التشخيص المبكر والعلاج يحسنان النتائج بشكل كبير. قد يعاني المرضى من:",
    "spinal38": "تحسن في جودة الحياة بعد العلاج الناجح",
    "spinal39": "انزعاج مؤقت بعد الجراحة أو الإجراءات الداخلية",
    "spinal40": "المراقبة المستمرة لضمان عدم تكرار التشوه أو تفاقمه",
    "spinal41": "العلاج الطبيعي لاستعادة الحركة والقوة إذا كانت الأعراض العصبية موجودة",
    "spinal42": "يلعب فريق رعاية متعدد التخصصات، بما في ذلك جراحي الأعصاب وأطباء الأعصاب وأخصائيي إعادة التأهيل، دورًا رئيسيًا في التعافي.",
    "spinal43": "العودة إلى الصفحة الرئيسية",
    "tvar1": "إصلاح الشريان الأورطي الصدري بالتدخل الوعائي (TVAR)",
    "tvar2": "دليل متعمق للإجراء والمؤشرات والنتائج",
