    "evar5": "إصلاح الشريان الأورطي بالتدخل الوعائي (EVAR) هو إجراء طفيف التوغل يُستخدم لعلاج تمدد الأوعية الدموية في الشريان الأورطي البطني (AAAs). يتضمن EVAR إدخال دعامة في الجزء الضعيف من الشريان الأورطي لتقويته ومنع تمزقه. لقد أحدثت هذه التقنية المتقدمة ثورة في إدارة تمدد الأوعية الدموية عن طريق تقديم بديل أكثر أمانًا وأقل توغلاً مقارنة بالجراحة المفتوحة التقليدية.",
