    "coarctation5": "تضيق الشريان الأورطي هو حالة خلقية يتم فيها تضييق جزء من الشريان الأورطي، مما يؤدي إلى تدفق دم محدود إلى الجزء السفلي من الجسم. يمكن أن يؤدي ذلك إلى ارتفاع ضغط الدم قبل منطقة التضيق وتدفق دم غير كافٍ بعدها. إذا لم يتم علاجه، فقد يؤدي إلى مضاعفات خطيرة، بما في ذلك فشل القلب أو السكتة الدماغية.",
    "coarctation6": "الاختلافات الرئيسية",
    "coarctation7": "تضيق خلقي في الشريان الأورطي",
    "coarctation8": "قد يظل بدون أعراض في الحالات الخفيفة",
