    "coarctation10": "يتطلب تدخلًا طبيًا أو جراحيًا مخصصًا",
    "coarctation11": "الأعراض",
    "coarctation12": "تختلف أعراض تضيق الشريان الأورطي بناءً على شدة التضيق. تشمل الأعراض الشائعة:",
    "coarctation13": "ارتفاع ضغط الدم، خاصة في الذراعين",
