    "coarctation20": "الأسباب وعوامل الخطر",
    "coarctation21": "تضيق الشريان الأورطي هو حالة خلقية تتطور قبل الولادة. ومع ذلك، يمكن أن تزيد بعض العوامل والحالات من احتمالية حدوثها:",
    "coarctation22": "متلازمات وراثية مثل متلازمة تيرنر",
    "coarctation23": "تاريخ عائلي من العيوب الخلقية في القلب",
