    "coarctation27": "يعتمد علاج تضيق الشريان الأورطي على شدة الحالة وصحة المريض العامة. تشمل الخيارات:",
    "coarctation28": "رأب الأوعية بالبالون: إجراء طفيف التوغل لتوسيع الجزء الضيق من الشريان الأورطي باستخدام قسطرة وبالون.",
    "coarctation29": "وضع الدعامة: إدخال دعامة للحفاظ على المنطقة الضيقة مفتوحة.",
