    "coarctation42": "الإجراءات الجراحية: تعافي أطول، عادةً من 4-6 أسابيع",
    "coarctation43": "المتابعة طويلة الأجل ضرورية لمراقبة ضغط الدم وضمان بقاء المنطقة المعالجة مفتوحة. غالبًا ما يوصى بتغييرات في نمط الحياة، مثل نظام غذائي صحي للقلب وممارسة التمارين الرياضية بانتظام، لمنع حدوث مضاعفات.",
    "coarctation44": "الخلاصة",
    "coarctation45": "تضيق الشريان الأورطي هو حالة خطيرة تتطلب تشخيصًا وعلاجًا سريعًا. مع التقدم في التقنيات طفيفة التوغل وخيارات الجراحة، يمكن لمعظم المرضى أن يعيشوا حياة صحية بعد العلاج. تعد المتابعات المنتظمة وإدارة ضغط الدم مفتاحًا للنجاح على المدى الطويل.",
    "coarctation46": "العودة إلى الصفحة الرئيسية",
    "leriche1": "متلازمة ليريشي",
