    "leriche4": "ما هي متلازمة ليريشي؟",
    "leriche5": "متلازمة ليريشي، المعروفة أيضًا باسم مرض انسداد الأبهر الحرقفي، هي حالة ناجمة عن تضييق أو انسداد الشريان الأبهر البطني والشرايين الحرقفية. يؤدي هذا الانسداد إلى تقليل تدفق الدم إلى الجزء السفلي من الجسم، مما يسبب مجموعة متنوعة من الأعراض التي تؤثر بشكل رئيسي على الساقين والحوض. ترتبط عادةً بتصلب الشرايين المتقدم.",
    "leriche6": "الاختلافات الرئيسية",
