    "leriche32": "الأدوية: أدوية لخفض الكوليسترول، والسيطرة على ضغط الدم، ومنع تجلط الدم (مثل الستاتينات، ومضادات الصفائح).",
    "leriche33": "الإجراءات داخل الأوعية: تقنيات طفيفة التوغل مثل رأب الأوعية والدعامات لفتح الشرايين المسدودة.",
