    "leriche44": "جراحة التجاوز: قد يستغرق التعافي عدة أسابيع، مع زيارات متابعة لمراقبة وظيفة الرقعة.",
    "leriche45": "يشمل الإدارة طويلة الأجل تغييرات في نمط الحياة، وفحوصات منتظمة، وعلاجًا مستمرًا للحالات المتعلقة بتصلب الشرايين.",
    "leriche46": "الخلاصة",
    "leriche47": "متلازمة ليريشي هي حالة خطيرة تتطلب تشخيصًا مبكرًا وتدخلًا. لقد حسّنت التقدمات في التقنيات داخل الأوعية والجراحية بشكل كبير النتائج، مما يسمح لمعظم المرضى باستعادة الحركة ونوعية الحياة. يعد إدارة عوامل الخطر أمرًا بالغ الأهمية لمنع التكرار والمضاعفات طويلة الأجل.",
    "leriche48": "العودة إلى الصفحة الرئيسية",
