    "tips5": "تحويلة الكبد البابية الجهازية عبر الوداجي (TIPS) هي إجراء طفيف التوغل مصمم لتقليل ارتفاع ضغط الدم في نظام الوريد البابي الناتج عن حالات مثل تليف الكبد. ينشئ الإجراء قناة داخل الكبد تربط الوريد البابي بالوريد الكبدي، مما يسمح للدم بتجاوز الكبد والتدفق مباشرة إلى الدورة الدموية الجهازية.",
