    "tips19": "تليف الكبد: تلف مزمن للكبد يؤدي إلى التندب وزيادة ضغط الوريد البابي.",
    "tips20": "تجلط الوريد البابي: جلطات دموية في الوريد البابي.",
    "tips21": "نزيف دوالي شديد: نزيف يهدد الحياة في المريء أو المعدة.",
