    "tips24": "تحويلة الكبد البابية الجهازية هي إجراء طفيف التوغل يتم تنفيذه بواسطة أخصائي الأشعة التداخلية. تشمل الخطوات الرئيسية ما يلي:",
    "tips25": "التحضير: يخضع المرضى لاختبارات التصوير وتحليل الدم لتقييم حالتهم.",
    "tips26": "إدخال القسطرة: يتم إدخال قسطرة صغيرة في الوريد في الرقبة وتوجيهها إلى الكبد.",
    "tips27": "وضع التحويلة: يتم إنشاء قناة في الكبد، ويتم وضع دعامة لربط الوريد البابي والأوردة الكبدية.",
    "tips28": "المتابعة بعد الإجراء: يخضع المرضى للمراقبة بحثًا عن المضاعفات وإجراء تصوير متابعة.",
    "tips29": "المخاطر والمضاعفات",
    "tips30": "على الرغم من أن تحويلة الكبد البابية الجهازية تعتبر آمنة بشكل عام، إلا أن المخاطر المحتملة تشمل:",
    "tips31": "النزيف أو العدوى",
    "tips32": "الاعتلال الدماغي الكبدي (الارتباك الناجم عن تراكم السموم)",
    "tips33": "انسداد أو تضيق التحويلة",
    "tips34": "فشل القلب لدى المرضى الذين يعانون من حالات موجودة مسبقًا",
    "tips35": "التعافي والمتابعة",
    "tips36": "يشمل التعافي بعد تحويلة الكبد البابية الجهازية ما يلي:",
    "tips37": "إقامة قصيرة في المستشفى: يتم إخراج معظم المرضى في غضون 1-2 أيام.",
    "tips38": "مواعيد متابعة: يلزم إجراء تصوير بالموجات فوق الصوتية بانتظام للتأكد من بقاء التحويلة مفتوحة.",
    "tips39": "تعديلات نمط الحياة: اتباع نظام غذائي منخفض الصوديوم، وتجنب الكحول، وممارسة التمارين بانتظام لدعم النتائج طويلة الأجل.",
    "tips40": "تعد المتابعة طويلة الأجل ضرورية لاكتشاف وإدارة المضاعفات مثل الاعتلال الدماغي أو خلل التحويلة.",
    "tips41": "الخلاصة",
    "tips42": "تحويلة الكبد البابية الجهازية هي إجراء ينقذ الحياة للمرضى الذين يعانون من مضاعفات ارتفاع ضغط الوريد البابي. مع التقدم في التكنولوجيا الطبية، أصبحت تحويلة الكبد البابية الجهازية خيارًا أكثر أمانًا وفعالية، مما يوفر تحسينًا في جودة الحياة وتقليل حالات الدخول إلى المستشفى. يعد التشخيص في الوقت المناسب والرعاية المنتظمة للمتابعة ضروريين لتحقيق نتائج ناجحة.",
    "tips43": "العودة إلى الصفحة الرئيسية",
