    "dips4": "ما هو DIPS؟",
    "dips5": "تحويلة الكبد البابية الجهازية المباشرة (DIPS) هي إجراء طفيف التوغل مصمم لعلاج مضاعفات ارتفاع ضغط الوريد البابي. يتضمن إنشاء اتصال مباشر بين الوريد البابي ووريد جهازي، مثل الوريد الأجوف السفلي، لتجاوز الكبد وتقليل الضغط العالي في نظام الوريد البابي. يعتبر DIPS مفيدًا بشكل خاص للمرضى الذين يعانون من أمراض الكبد المتقدمة أو عندما لا تكون الإجراءات الأخرى ممكنة.",
    "dips6": "الميزات الرئيسية لتحويلة DIPS",
