    "dips8": "فعال في إدارة مضاعفات مثل نزيف الدوالي والاستسقاء المقاوم",
    "dips9": "يستخدم توجيه الصور (الموجات فوق الصوتية والتنظير التألقي) بدقة",
    "dips10": "يمكن أن يكون بديلاً عن تحويلة الكبد البابية الجهازية التقليدية (TIPS)",
