    "dips13": "نزيف الدوالي المتكرر الذي لا يمكن السيطرة عليه بالعلاجات التنظيرية",
    "dips14": "الاستسقاء المقاوم على الرغم من العلاج الطبي الأمثل",
    "dips15": "متلازمة الكبد الكلوي في حالات معينة",
    "dips16": "الانصباب الجنبي الكبدي الشديد",
    "dips17": "تجلط الوريد البابي حيث لا يمكن إجراء تحويلة TIPS",
