    "ptc5": "تصوير القنوات الصفراوية عبر الجلد (PTC) هو إجراء طفيف التوغل يستخدم لتشخيص وعلاج انسداد القنوات الصفراوية. يتضمن إدخال إبرة رفيعة عبر الجلد إلى الكبد لتصور القنوات الصفراوية باستخدام صبغة التباين وتقنيات التصوير. يمكن أيضًا لـ PTC إجراء تدخلات علاجية مثل وضع الدعامات أو تصريف الصفراء لتخفيف الانسدادات الناتجة عن حالات مثل الأورام أو حصوات المرارة أو التضيقات.",
