    "vv5": "الدوالي الوريدية هي أوردة متضخمة وملتوية غالبًا ما تظهر باللون الأزرق أو الأرجواني تحت الجلد. تحدث عندما تتعطل الصمامات في الأوردة، مما يتسبب في تجمع الدم بدلاً من التدفق بكفاءة إلى القلب. بينما تصيب الساقين عادة، يمكن أن تتطور الدوالي في أجزاء أخرى من الجسم. على الرغم من أنها تكون عادةً مصدر قلق تجميلي، إلا أن الحالات الشديدة يمكن أن تؤدي إلى عدم الراحة والمضاعفات.",
