    "tavi1": "زرع الصمام الأبهري عبر القسطرة (TAVI)",
    "tavi2": "حل طفيف التوغل لأمراض الصمام الأبهري",
    "tavi3": "رسم توضيحي لزرع الصمام الأبهري عبر القسطرة",
    "tavi4": "ما هو TAVI؟",
    "tavi5": "زرع الصمام الأبهري عبر القسطرة (TAVI)، المعروف أيضًا باسم استبدال الصمام الأبهري عبر القسطرة (TAVR)، هو إجراء طفيف التوغل مصمم لعلاج تضيق الصمام الأبهري. يحدث هذا المرض عندما يصبح الصمام الأبهري ضيقًا، مما يعيق تدفق الدم من القلب إلى باقي الجسم. يقوم TAVI باستبدال الصمام التالف دون الحاجة إلى جراحة القلب المفتوح، مما يوفر بديلاً أكثر أمانًا للمرضى المعرضين لمخاطر عالية أو غير القابلين للجراحة.",
