    "avm32": "نەشتەرگەریی تیشکی (Radiosurgery): چارەسەری تیشکی چڕکراوە بۆ داخستنی AVM بە تێپەڕبوونی کات، زۆرجار بۆ AVMـی قووڵ یان بچووک بەکاردێت.",
    "avm33": "پرۆسەی نەشتەرگەری",
