    "avm35": "نەشتەرگەریی کراوە: لە ژێر بێهۆشیی گشتیدا ئەنجام دەدرێت، کاسەی سەر دەکرێتەوە (Craniotomy) بۆ دەرخستن و لابردنی AVM. زۆرجار بۆ AVMـی سەر ڕووی مێشک بەکاردێت.",
    "avm36": "چارەسەری ناو بۆریی خوێن: کاتیتەرێک لە ڕێگەی خوێنبەری ڕانەوە دەگەیەنرێتە AVM و مادە دادەنێت بۆ ڕاگرتنی ڕۆیشتنی خوێن.",
    "avm37": "نەشتەرگەریی تیشکی: ڕێکارێکی بێ نەشتەرگەرییە کە تیشکی زۆر چڕکراوە ئاراستەی AVM دەکرێت، و دەبێتە هۆی بچووکبوونەوە و داخرانی لە ماوەی چەند مانگ یان چەند ساڵێکدا.",
