    "cardiacAblation47": "گەڕانەوە",
    "chemoembolization1": "کیمۆئیمبۆلیزەیشن (Chemoembolization)",
    "chemoembolization2": "کیمۆئیمبۆلیزەیشن (Chemoembolization)",
    "chemoembolization3": "ڕێگایەکی ئامانجدار بۆ چارەسەری شێرپەنجە",
    "chemoembolization4": "وێنەی ڕوونکردنەوەی کیمۆئیمبۆلیزەیشن",
    "chemoembolization5": "کیمۆئیمبۆلیزەیشن چییە؟",
    "chemoembolization6": "کیمۆئیمبۆلیزەیشن ڕێکارێکی کەم‌دەستتێوەردانە بۆ چارەسەرکردنی شێرپەنجە، بەتایبەتی شێرپەنجەی جگەر. ئەم تەکنیکە بڕێکی زۆری چارەسەری کیمیایی ڕاستەوخۆ دەگەیەنێتە گرێکە و لە هەمان کاتدا خوێنی گرێکە دەبڕێت، ئەمەش کاریگەریی چارەسەرەکە زیاد دەکات و کاریگەرییە لاوەکییەکانی سەر هەموو لەش کەم دەکاتەوە. کیمۆئیمبۆلیزەیشن زۆرجار بەکاردێت کاتێک نەشتەرگەری یان چارەسەرەکانی تر گونجاو نین.",
    "chemoembolization7": "تایبەتمەندییە سەرەکییەکانی کیمۆئیمبۆلیزەیشن",
    "chemoembolization8": "ڕاستەوخۆ گرێکان دەکاتە ئامانج و شانە تەندروستەکان دەپارێزێت",
    "chemoembolization9": "گەیاندنی ناوچەیی چارەسەری کیمیایی لەگەڵ داخستنی بۆریی خوێن (Embolization) تێکەڵ دەکات",
    "chemoembolization10": "زیاتر بۆ شێرپەنجەکانی جگەر وەک شێرپەنجەی خانەکانی جگەر (Hepatocellular carcinoma) بەکاردێت",
    "chemoembolization11": "کەم‌دەستتێوەردانە و بە ڕێنماییی وێنەگرتن ئەنجام دەدرێت",
    "chemoembolization12": "کەی پێویست بە کیمۆئیمبۆلیزەیشن دەکات؟",
    "chemoembolization13": "کیمۆئیمبۆلیزەیشن بۆ ئەمانە بەکاردێت:",
    "chemoembolization14": "شێرپەنجەی جگەر: هەم شێرپەنجە سەرەتایییەکانی جگەر و هەم شێرپەنجەی بڵاوبووەوە بۆ جگەر",
    "chemoembolization15": "ئەو نەخۆشانەی نەشتەرگەرییان بۆ ناکرێت: نەخۆشانێک کە گونجاو نین بۆ نەشتەرگەری یان چاندنی جگەر",
    "chemoembolization16": "چارەسەری سووککەرەوە: بۆ بچووککردنەوەی گرێکان و کەمکردنەوەی نیشانەکان",
    "chemoembolization17": "پردێک بۆ نەشتەرگەری: بۆ کۆنتڕۆڵکردنی قەبارەی گرێ پێش نەشتەرگەریی کۆتایی یان چاندن بەکاردێت",
    "chemoembolization18": "کیمۆئیمبۆلیزەیشن چۆن ئەنجام دەدرێت؟",
    "chemoembolization19": "ڕێکارەکە لەلایەن پزیشکی پسپۆڕی تیشکی دەستتێوەردانەوە ئەنجام دەدرێت:",
    "chemoembolization20": "دەستگەیشتن: کاتیتەرێک دەخرێتە ناو خوێنبەری ڕان لە ناوگەڵدا.",
    "chemoembolization21": "ئاڕاستەکردن: بە ڕێنماییی وێنەگرتن، کاتیتەرەکە ئاڕاستەی ئەو بۆرییانەی خوێن دەکرێت کە خوێن بە گرێکە دەگەیەنن.",
    "chemoembolization22": "گەیاندنی چارەسەری کیمیایی: دەرمانەکانی چارەسەری کیمیایی ڕاستەوخۆ دەگەیەنرێنە گرێکە.",
    "chemoembolization23": "داخستنی بۆریی خوێن (Embolization): تەنۆلکەی زۆر بچووک دەدرێت بۆ بڕینی خوێن، و چارەسەرە کیمیاییەکە لە شوێنی گرێکەدا دەمێنێتەوە.",
    "chemoembolization24": "سوودەکانی کیمۆئیمبۆلیزەیشن",
