    "chemoembolization26": "گرێکان بە وردی دەکاتە ئامانج و کاریگەرییە لاوەکییەکانی چارەسەری کیمیایی لەسەر هەموو لەش کەم دەکاتەوە",
    "chemoembolization27": "قەبارەی گرێ کەم دەکاتەوە و نیشانەکان و کوالیتیی ژیان باشتر دەکات",
    "chemoembolization28": "کەم‌دەستتێوەردانە و ماوەی چاکبوونەوەی کورتترە بە بەراورد بە نەشتەرگەری",
    "chemoembolization29": "لەوانەیە تەمەنی ئەو نەخۆشانە درێژ بکاتەوە کە شێرپەنجەکەیان نەشتەرگەریی بۆ ناکرێت",
    "chemoembolization30": "مەترسی و ئاڵۆزییە ئەگەرییەکان",
