    "chemoembolization32": "ئازار یان ناڕەحەتی لە ناوچەی چارەسەرکراودا",
    "chemoembolization33": "دڵتێکهەڵاتن، تا یان ماندوێتی وەک بەشێک لە سیندرۆمی دوای داخستنی بۆریی خوێن (Post-embolization syndrome)",
    "chemoembolization34": "تێکچوونی کارکردنی جگەر یان زیانگەیاندن پێی لە حاڵەتی دەگمەندا",
