    "chemoembolization37": "چاکبوونەوە و بەڕێوەبردنی درێژخایەن",
    "chemoembolization38": "چاکبوونەوە دوای کیمۆئیمبۆلیزەیشن بەگشتی ئەمانە لەخۆدەگرێت:",
    "chemoembolization39": "مانەوە لە نەخۆشخانە بۆ 1-2 ڕۆژ بۆ چاودێریکردنی ئاڵۆزییەکان",
    "chemoembolization40": "کۆنتڕۆڵکردنی نیشانەکانی وەک ئازار یان دڵتێکهەڵاتن بە دەرمانی نووسراو",
    "chemoembolization41": "وێنەگرتنی بەدواداچوون بۆ هەڵسەنگاندنی وەڵامدانەوەی گرێکە",
    "chemoembolization42": "چاودێریی بەردەوامی کارکردنی جگەر و تەندروستیی گشتی",
    "chemoembolization43": "زۆربەی نەخۆشان ئاسوودەبوونێکی بەرچاو لە نیشانەکان ئەزموون دەکەن و دەتوانن لە ماوەی هەفتەیەکدا بگەڕێنەوە بۆ چالاکییە ئاسایییەکانیان. لەوانەیە بەپێی وەڵامدانەوەی گرێکە پێویست بە چارەسەری زیاتر بێت.",
    "chemoembolization44": "گەڕانەوە",
    "chevar1": "چاککردنەوەی ئەئورت لە ناو بۆرییەوە بە شێوازی دووکەڵکێش (CHEVAR)",
    "chevar2": "ڕێنمایییەکی گشتگیر دەربارەی ڕێکار، سوود و مەترسییەکان",
    "chevar3": "وێنەی ڕوونکردنەوەی CHEVAR",
    "chevar4": "CHEVAR چییە؟",
    "chevar5": "چاککردنەوەی ئەئورت لە ناو بۆرییەوە بە شێوازی دووکەڵکێش (CHEVAR) تەکنیکێکی پێشکەوتووی کەم‌دەستتێوەردانە بۆ چارەسەرکردنی ئەنیوریزمە ئاڵۆزەکانی ئەئورت کە لقە خوێنبەرەکان دەگرنەوە، وەک خوێنبەرەکانی گورچیلە یان ڕیخۆڵە. ڕێکارەکە ستێنتی زیادە بەکاردەهێنێت کە پێیان دەوترێت «دووکەڵکێش» (Chimneys)، لە تەنیشت ستێنت گرافتی سەرەکی، بۆ دڵنیابوون لە بەردەوامیی ڕۆیشتنی خوێن بۆ لقە گرنگەکان لە کاتی چارەسەرکردنی ئەنیوریزمەکەدا.",
    "chevar6": "تایبەتمەندییە سەرەکییەکان",
    "chevar7": "ڕێگە دەدات بە چارەسەرکردنی ئەنیوریزمی نزیک خوێنبەرە گرنگەکان بەبێ نەشتەرگەریی کراوە",
    "chevar8": "ستێنتە دووکەڵکێشەکان ڕۆیشتنی خوێن بۆ لقە بۆرییەکان دەپارێزن",
    "chevar9": "بە شێوەیەکی زۆر گونجاو دەکرێت بۆ پێکهاتەی لەشی هەر نەخۆشێک",
    "chevar10": "کەم‌دەستتێوەردانە و ماوەی چاکبوونەوەی کورتترە",
    "chevar11": "کەی CHEVAR پێویستە",
    "chevar12": "CHEVAR بۆ ئەو نەخۆشانە دەگونجێت کە ئەمانەیان هەیە:",
