    "chevar44": "CHEVAR بژاردەیەکی پێشکەوتووە بۆ چارەسەرکردنی ئەنیوریزمە ئاڵۆزەکانی ئاورتا کە لقە خوێنبەرەکان دەگرێتەوە. سروشتی کەم دەستێوەردانی و توانای پاراستنی ڕۆیشتنی خوێنی گرنگ، دەیکاتە چارەسەرێکی بەنرخ بۆ ئەو نەخۆشانەی بارودۆخی جەستەیی ئاڵۆزیان هەیە، و دەرئەنجامی باشتر و کوالیتی ژیانی بەرزتر مسۆگەر دەکات.",
