    "coarctation5": "تەنگبوونەوەی ئاورتا بارودۆخێکی زگماکییە کە تێیدا بەشێک لە ئاورتا تەسک دەبێتەوە، ئەمەش دەبێتە هۆی سنووردارکردنی ڕۆیشتنی خوێن بۆ بەشی خوارەوەی جەستە. ئەمە دەتوانێت ببێتە هۆی بەرزبوونەوەی پەستانی خوێن پێش شوێنی تەنگبوونەوەکە و کەمی ڕۆیشتنی خوێن لە دوای ئەو شوێنە. ئەگەر چارەسەر نەکرێت، لەوانەیە ببێتە هۆی ئاڵۆزیی مەترسیدار، لەوانە شکستی دڵ یان جەڵتەی مێشک.",
