    "coarctation43": "بەدواداچوونی درێژخایەن پێویستە بۆ چاودێریکردنی پەستانی خوێن و دڵنیابوون لەوەی شوێنە چارەسەرکراوەکە کراوە دەمێنێتەوە. زۆرجار گۆڕانکاری لە شێوازی ژیاندا، وەک خۆراکی تەندروست بۆ دڵ و وەرزشی بەردەوام، پێشنیار دەکرێت بۆ ڕێگریکردن لە ئاڵۆزییەکان.",
