    "cto22": "بەرزیی پەستانی خوێن: بە تێپەڕبوونی کات زیان بە بۆرییەکانی خوێن دەگەیەنێت",
    "cto23": "شەکرە: مەترسیی گیرانی خوێنبەرەکان زیاد دەکات",
    "cto24": "جگەرەکێشان: زیان بە چینی ناوەوەی بۆرییەکانی خوێن دەگەیەنێت",
    "cto25": "قەڵەوی: پەیوەندیدارە بە چەندین فاکتەری مەترسیی دڵ و بۆرییەکانی خوێن",
    "cto26": "مێژووی خێزانی: ئامادەییی بۆماوەیی بۆ نەخۆشیی خوێنبەرە تاجییەکان",
    "cto27": "CTO چۆن دەستنیشان و چارەسەر دەکرێت؟",
    "cto28": "دەستنیشانکردن وێنەگرتن و پشکنینی کارکردن لەخۆدەگرێت بۆ هەڵسەنگاندنی ئاستی گیرانەکە:",
    "cto29": "پشکنینی فشار (Stress Test): کاردانەوەی دڵ بەرامبەر بە فشاری جەستەیی یان دەرمانی هەڵدەسەنگێنێت",
    "cto30": "وێنەگرتنی خوێنبەرە تاجییەکان (Coronary Angiography): وێنەی ورد لە خوێنبەرە تاجییەکان دەدات",
    "cto31": "وێنەگرتنی خوێنبەرەکان بە CT (CT Angiography): وێنەگرتنێکی بێ دەستێوەردان بۆ دۆزینەوەی گیرانەکان",
    "cto32": "چارەسەر جەخت دەکاتە سەر گەڕاندنەوەی ڕۆیشتنی خوێن و کۆنترۆڵکردنی نیشانەکان:",
    "cto33": "دەرمانەکان: دەرمانی دژە ئەنجاینا، دەرمانی کەمکەرەوەی کۆلیسترۆڵ و دەرمانی شلکەرەوەی خوێن لەخۆدەگرێت",
    "cto34": "دەستێوەردانی خوێنبەرە تاجییەکان لە ڕێگەی پێستەوە (PCI): ڕێکارێکی کەم دەستێوەردانە کە تەکنیکی تایبەت بەکاردەهێنێت بۆ کردنەوەی خوێنبەرە گیراوەکە",
    "cto35": "نەشتەرگەریی بای پاسی خوێنبەرە تاجییەکان (CABG): بژاردەیەکی نەشتەرگەرییە بۆ ئەو حاڵەتانەی بۆ PCI گونجاو نین",
    "cto36": "ڕێکارە تێکەڵەکان (Hybrid): نەشتەرگەریی کراوە و دەستێوەردانی کاتیتەر پێکەوە بەکاردەهێنێت بۆ حاڵەتە ئاڵۆزەکان",
    "cto37": "مەترسی و ئاڵۆزییە ئەگەرییەکان",
    "cto38": "هەرچەندە چارەسەرەکانی CTO بە گشتی سەلامەتن، ئاڵۆزییە ئەگەرییەکان بریتین لە:",
    "cto39": "خوێنبەربوون یان هەوکردن لە شوێنی تێخستنی کاتیتەر",
