    "leriche5": "سەندرۆمی لێریش، کە بە نەخۆشیی گیرانی ئاورتا و خوێنبەرە ئیلیاکەکان (Aortoiliac Occlusive Disease) یش ناسراوە، بارودۆخێکە کە بەهۆی تەنگبوونەوە یان گیرانی ئاورتای سک و خوێنبەرە ئیلیاکەکانەوە دروست دەبێت. ئەم گیرانە ڕۆیشتنی خوێن بۆ بەشی خوارەوەی جەستە کەم دەکاتەوە، و دەبێتە هۆی چەندین نیشانە کە بە شێوەیەکی سەرەکی قاچەکان و ناوچەی حەوز دەگرنەوە. زۆرجار پەیوەندیدارە بە ڕەقبوونی پێشکەوتووی خوێنبەرەکانەوە (Atherosclerosis).",
    "leriche6": "جیاکەرەوە سەرەکییەکان",
