    "leriche44": "نەشتەرگەری بای پاس: لەوانەیە چاکبوونەوە چەند هەفتەیەک بخایەنێت، لەگەڵ سەردانی بەدواداچوون بۆ چاودێریکردنی کارکردنی گرافتەکە.",
    "leriche45": "بەڕێوەبردنی درێژخایەن بریتییە لە گۆڕانکاری لە شێوازی ژیان، پشکنینی بەردەوام و چارەسەری بەردەوام بۆ ئەو نەخۆشییانەی پەیوەندییان بە ڕەقبوونی خوێنبەرەکانەوە هەیە.",
    "leriche46": "کۆتایی",
    "leriche47": "نەخۆشی لێریش نەخۆشییەکی جددییە کە پێویستی بە دەستنیشانکردنی زوو و دەستێوەردان هەیە. پێشکەوتنەکانی ڕێگای ناو خوێنبەر و نەشتەرگەری ئەنجامەکانیان بە شێوەیەکی بەرچاو باشتر کردووە، و ڕێگە بە زۆربەی نەخۆشەکان دەدەن جووڵە و کوالیتی ژیانیان بگەڕێننەوە. بەڕێوەبردنی بەردەوامی فاکتەرەکانی مەترسی گرنگە بۆ ڕێگرتن لە دووبارەبوونەوە و ئاڵۆزییە درێژخایەنەکان.",
    "leriche48": "گەڕانەوە",
    "mi1": "جەڵتەی دڵ (MI)",
