    "mi4": "جەڵتەی دڵ (MI) چییە؟",
    "mi5": "جەڵتەی دڵ (Myocardial Infarction - MI) کاتێک ڕوودەدات کە سووڕی خوێن بۆ بەشێک لە دڵ دەگیرێت، زۆرجار بەهۆی مەیینی خوێن یان کەڵەکەبوونی پلاک لە خوێنبەرە تاجییەکاندا (کۆرۆنەری). ئەم پچڕانە ماسولکەی دڵ لە ئۆکسجین بێبەش دەکات و دەبێتە هۆی زیانگەیشتن یان مردنی شانەی دڵ. دەستنیشانکردن و چارەسەری خێرا زۆر گرنگن بۆ ڕزگاربوون و چاکبوونەوە.",
