    "ptc5": "وێنەگرتنی جۆگەکانی زراو بە ڕێگای پێست و جگەر (PTC) پرۆسەیەکی کەمدەستێوەردانە بۆ دەستنیشانکردن و چارەسەری گیرانی جۆگەکانی زراو بەکاردێت. تێیدا دەرزییەکی باریک بە ناو پێستدا دەخرێتە ناو جگەر بۆ بینینی جۆگەکانی زراو بە بەکارهێنانی ماددەی ڕەنگاوی و ڕێگاکانی وێنەگرتن. هەروەها PTC ڕێگە بە دەستێوەردانی چارەسەری دەدات وەک دانانی ستێنت یان دەرکردنی زراو بۆ لابردنی ئەو گیرانانەی بەهۆی نەخۆشی وەک گرێ، بەردی زراو یان تەسکبوونەوە دروست بوون.",
    "ptc6": "خاڵە جیاکەرەوە سەرەکییەکان",
    "ptc7": "بینینی ڕاستەوخۆی جۆگەکانی زراو بە وێنەگرتنی ماددەی ڕەنگاوی",
