    "ptc27": "ئامادەکاری: نەخۆش پشکنینی وێنەگرتن و پشکنینی خوێن دەکات بۆ هەڵسەنگاندنی کارکردنی جگەر و دڵنیابوون لە نەبوونی هەوکردن.",
    "ptc28": "خستنە ناوەوەی دەرزی: دەرزییەک بە ناو پێستدا دەخرێتە ناو جگەر بە ڕێنمایی سۆنار یان فلۆرۆسکۆپی.",
