    "ptc41": "چاودێری بۆری دەرکردن: ئەگەر بۆری دەرکردنی زراو دانرابێت، چاودێری دروست و بەدواداچوونی بەردەوام پێویستن.",
    "ptc42": "گۆڕانکاری لە شێوازی ژیان: خۆراکی کەم چەوری و دوورکەوتنەوە لە ئەلکهول دەتوانن پشتگیری تەندروستی جگەر بکەن.",
    "ptc43": "وێنەگرتن و بەدواداچوونی بەردەوام گرنگن بۆ دڵنیابوون لە کارکردنی ستێنت یان بۆری دەرکردنەکە و چاودێریکردنی دووبارەبوونەوەی گیران.",
    "ptc44": "کۆتایی",
    "ptc45": "وێنەگرتنی جۆگەکانی زراو بە ڕێگای پێست و جگەر (PTC) پرۆسەیەکی زۆر کاریگەرە بۆ دەستنیشانکردن و چارەسەری گیرانی جۆگەکانی زراو. بەهۆی توانای دووانەی دەستنیشانکردن و چارەسەرەوە، PTC ئاسوودەیی دەستبەجێ لە نیشانەکان دەبەخشێت و کوالیتی ژیان باشتر دەکات. دۆزینەوەی زوو و دەستێوەردانی بەکات کلیلی ئەنجامی سەرکەوتوون.",
    "ptc46": "گەڕانەوە",
    "spinal1": "AVM ی بڕبڕەی پشت",
    "spinal2": "تێگەیشتن لە شێواوی خوێنبەر و خوێنهێنەرەکانی بڕبڕەی پشت",
    "spinal3": "وێنەی ڕوونکەرەوەی AVM ی بڕبڕەی پشت",
    "spinal4": "AVM ی بڕبڕەی پشت چییە؟",
    "spinal5": "AVM ی بڕبڕەی پشت (شێواوی خوێنبەر و خوێنهێنەری بڕبڕەی پشت) تێکئاڵانێکی نائاسایی بۆرییەکانی خوێنە لە ناو یان دەوری مۆخی بڕبڕەی پشتدا. ئەم شێواوییانە ڕێڕەوی ئاسایی خوێن لە نێوان خوێنبەر و خوێنهێنەرەکاندا تێک دەدەن، و لەوانەیە ببنە هۆی کەمبوونەوەی گەیاندنی ئۆکسجین بۆ مۆخی بڕبڕەی پشت. بە تێپەڕبوونی کات، ئەمە دەتوانێت ببێتە هۆی زیانی بەردەوام یان نیشانەی دەماریی لەناکاو ئەگەر AVM ەکە بتەقێت و خوێنبەربوون (نزیف) دروست بکات.",
    "spinal6": "خاڵە جیاکەرەوە سەرەکییەکان",
    "spinal7": "پەیوەندی نائاسایی لە نێوان خوێنبەر و خوێنهێنەرەکانی مۆخی بڕبڕەی پشتدا",
