    "spinal20": "هۆکاری ورد ی AVM ی بڕبڕەی پشت زۆرجار نەزانراوە، بەڵام وا باوەڕ دەکرێت لە کاتی گەشەی کۆرپەلەدا دروست ببن. هەندێک فاکتەر و نەخۆشی پەیوەست بە AVM ی بڕبڕەی پشت بریتین لە:",
    "spinal21": "فاکتەرە زگماکییەکان: شێواوی کە لە کاتی لەدایکبوونەوە هەیە",
    "spinal22": "نەخۆشییە بۆماوەییەکان: وەک تێلانجێکتازیای خوێنبەربوونی بۆماوەیی (HHT)",
    "spinal23": "برینداربوون: زیانگەیشتن بە بۆرییەکانی خوێنی بڕبڕەی پشت لەوانەیە لە حاڵەتی دەگمەندا هۆکار بێت",
    "spinal24": "هەوکردنەکان: هەندێک هەوکردن لەوانەیە ببنە هۆی ناڕێکی بۆرییەکانی خوێن",
    "spinal25": "دەستنیشانکردن",
    "spinal26": "دەستنیشانکردنی AVM ی بڕبڕەی پشت بریتییە لە تێکەڵەیەک لە هەڵسەنگاندنی کلینیکی و پشکنینەکانی وێنەگرتن بۆ دڵنیابوون لە بوونی بۆری خوێنی نائاسایی. ئامرازە باوەکانی دەستنیشانکردن بریتین لە:",
    "spinal27": "MRI (وێنەگرتن بە لەرەلەری موگناتیسی): وێنەی ورد لە مۆخی بڕبڕەی پشت و شانەکانی دەوروبەری دابین دەکات",
    "spinal28": "MRA (ئەنجیۆگرافی بە لەرەلەری موگناتیسی): بۆ بینینی سووڕی خوێن و دۆزینەوەی ناڕێکییەکان بەکاردێت",
    "spinal29": "ئەنجیۆگرافی بڕبڕەی پشت: پرۆسەیەک بە کاتیتەر بۆ نەخشەکێشانی بۆرییەکانی خوێنی بڕبڕەی پشت",
    "spinal30": "بژاردەکانی چارەسەر",
    "spinal31": "چارەسەری AVM ی بڕبڕەی پشت پشت بە چەند فاکتەرێک دەبەستێت وەک نیشانەکانی نەخۆش، قەبارە و شوێنی AVM ەکە و مەترسی تەقین. چارەسەرە باوەکان بریتین لە:",
    "spinal32": "داخستنی خوێنبەر (Embolization): پرۆسەیەکی کەمدەستێوەردانە کە تێیدا کاتیتەر بەکاردێت بۆ لێدانی ماددەیەک لە AVM ەکە بۆ گرتنی سووڕی خوێن و بچووککردنەوەی قەبارەکەی.",
    "spinal33": "لابردنی نەشتەرگەری: لابردنی AVM ەکە بە نەشتەرگەری ورد (microsurgery). ئەمە زۆرجار بۆ AVM ی دەستپێگەیشتوو و بە نیشانە بەکاردێت.",
    "spinal34": "نەشتەرگەری تیشکی (Radiosurgery): پرۆسەیەکی بێ بڕینە کە تیشکی چڕکراوە بەکاردەهێنێت بۆ داخستنی بۆرییە نائاساییەکان بە تێپەڕبوونی کات.",
    "spinal35": "چاودێریکردن: بۆ AVM ی بچووک و بێ نیشانە، لەوانەیە پزیشکەکان ڕاسپاردەی چاودێریکردنی نەخۆشییەکە بکەن بە وێنەگرتنی بەردەوام.",
    "spinal36": "وەک نەخۆش چاوەڕێی چی بکەیت",
    "spinal37": "ژیان لەگەڵ AVM ی بڕبڕەی پشت دەتوانێت قورس بێت، بەڵام دەستنیشانکردن و چارەسەری زوو ئەنجامەکان زۆر باشتر دەکەن. لەوانەیە نەخۆشەکان ئەمانە ببینن:",
    "spinal38": "باشتربوونی کوالیتی ژیان دوای چارەسەری سەرکەوتوو",
