    "spinal41": "چارەسەری سرووشتی (فیزیۆتێراپی) بۆ گەڕاندنەوەی جووڵە و هێز ئەگەر نیشانەی دەماری هەبووبێت",
    "spinal42": "تیمێکی چاودێری فرە پسپۆڕی، لەوانە نەشتەرگەرانی دەمار و مێشک، پزیشکانی دەمار و پسپۆڕانی بووژانەوە، ڕۆڵێکی سەرەکی لە چاکبوونەوەدا دەگێڕن.",
