    "stroke5": "جەڵتەی مێشک کاتێک ڕوودەدات کە گەیشتنی خوێن بۆ بەشێک لە مێشک دەپچڕێت یان کەم دەبێتەوە، و ڕێگری دەکات لەوەی شانەی مێشک ئۆکسجین و ماددە خۆراکییە پێویستەکان وەربگرێت. لە ماوەی چەند خولەکێکدا خانەکانی مێشک دەست بە مردن دەکەن، بۆیە جەڵتەی مێشک حاڵەتێکی فریاکەوتنی پزیشکییە و پێویستی بە چارەسەری خێرا هەیە بۆ کەمکردنەوەی زیانی مێشک و ئاڵۆزییەکان.",
