    "tips5": "پەیوەندکەری دەماری دەروازەیی-گشتی لەناو جگەر لە ڕێگەی دەماری ملەوە (TIPS) پرۆسەیەکی کەمدەستێوەردانە بۆ کەمکردنەوەی پەستانی بەرزی خوێن لە سیستەمی دەماری دەروازەیی (portal vein) کە بەهۆی بارودۆخی وەک جگەرڕەقبوونەوە (cirrhosis) دروست دەبێت. لەم پرۆسەیەدا ڕێڕەوێک لەناو جگەردا دروست دەکرێت کە دەماری دەروازەیی بە دەماری جگەرەوە دەبەستێتەوە، بەمەش خوێن بەلای جگەردا تێدەپەڕێت و ڕاستەوخۆ دەڕژێتە ناو سووڕی گشتیی خوێنەوە.",
