    "tips40": "چاودێریی درێژخایەن زۆر گرنگە بۆ دۆزینەوە و بەڕێوەبردنی ئاڵۆزییەکانی وەک تێکچوونی مێشک بەهۆی جگەرەوە یان تێکچوونی کارکردنی پەیوەندکەرەکە.",
    "tips41": "دەرئەنجام",
    "tips42": "TIPS ی جگەر پرۆسەیەکی ژیانڕزگارکەرە بۆ ئەو نەخۆشانەی ئاڵۆزییەکانی بەرزیی پەستانی دەماری دەروازەییان هەیە. بە پێشکەوتنی تەکنەلۆژیای پزیشکی، TIPS بووەتە بژاردەیەکی سەلامەتتر و کاریگەرتر کە کوالیتیی ژیان باشتر دەکات و ژمارەی مانەوە لە نەخۆشخانە کەم دەکاتەوە. دەستنیشانکردنی لەکاتی خۆی و چاودێریی بەردەوامی بەدواداچوون بۆ گەیشتن بە ئەنجامی سەرکەوتوو پێویستن.",
