    "stenting5": "دانانی ستێنت لە ڕێگەی جگەرەوە پرۆسەیەکی کەمدەستێوەردانە بۆ کردنەوەی جۆگەکانی زەرداو کە گیراون یان تەسک بوونەتەوە، لە ڕێگەی دانانی ستێنتێکەوە تاکو زەرداو بە ئازادی لە جگەرەوە بۆ ڕیخۆڵەکان بڕوات. بە زۆری لە حاڵەتەکانی گیرانی جۆگەی زەرداودا بەکاردێت کە بەهۆی تەسکبوونەوە، گرێ (تومۆر) یان ئاڵۆزییەکانی نەخۆشییەکانی جگەرەوە دروست دەبن.",
