    "venus5": "خوێنمەیینی دەمار بریتییە لە دروستبوونی خوێنمەیین (thrombus) لەناو دەمارێکدا. دەتوانێت لە دەمارە ڕووکەشییەکاندا (superficial thrombophlebitis) یان لە دەمارە قووڵەکاندا (خوێنمەیینی دەماری قووڵ، DVT) ڕووبدات. خوێنمەیینی دەماری قووڵ مەترسیدارترین جۆرە، چونکە خوێنمەیینەکە دەتوانێت جیا ببێتەوە و بگاتە سییەکان، و ببێتە هۆی بارودۆخێکی ئەگەری کوشندە کە پێی دەوترێت گیرانی خوێنبەری سی (PE). دۆزینەوە و چارەسەری زوو بۆ ڕێگریکردن لە ئاڵۆزییە سەختەکان زۆر گرنگە.",
