    "venus29": "دژە-مەیینەکان (Anticoagulants): دەرمانی شلکەرەوەی خوێن (وەک هێپارین، وارفارین یان دژە-مەیینە ڕاستەوخۆکانی ڕێگەی دەم) بۆ ڕێگریکردن لە گەورەبوونی خوێنمەیین و کەمکردنەوەی مەترسیی دروستبوونی خوێنمەیینی نوێ.",
