    "venus46": "ماوەی چاکبوونەوە جیاوازە؛ حاڵەتە سووکەکان لە ماوەی چەند هەفتەیەکدا چاک دەبنەوە و حاڵەتە سەختەکان پێویستیان بە چەند مانگێک چارەسەری دژە-مەیین هەیە.",
