function changeLanguage(lang) {
  if (!translations[lang]) lang = "en";
  try { localStorage.setItem("language", lang); } catch (e) {}

  const currentLanguage = document.getElementById("currentLanguage");
  if (currentLanguage) currentLanguage.textContent = lang.toUpperCase();

  // Translate every element whose id is a translation key.
  // Missing entries fall back to English, then to the page's original text.
  document.querySelectorAll("[id]").forEach((element) => {
    const key = element.id;
    const known = translations.en[key] || (translations.ar && translations.ar[key]) || (translations.kr && translations.kr[key]);
    if (!known) return;
    const isPlaceholder = element.hasAttribute("placeholder");
    if (element.dataset.i18nOrig === undefined) {
      element.dataset.i18nOrig = isPlaceholder ? element.getAttribute("placeholder") : element.textContent.trim();
      if (!isPlaceholder) element.__i18nHtml = element.innerHTML; // keep original markup for English
    }
    const value = translations[lang][key] || translations.en[key];
    if (isPlaceholder) element.setAttribute("placeholder", value || element.dataset.i18nOrig);
    else if (element.tagName === "TITLE") document.title = value || element.dataset.i18nOrig;
    else if (value) element.textContent = value;
    else if (element.__i18nHtml !== undefined) element.innerHTML = element.__i18nHtml;
  });

  const isRTL = lang === "ar" || lang === "kr";
  document.documentElement.dir = isRTL ? "rtl" : "ltr";
  document.documentElement.lang = lang === "kr" ? "ckb" : lang;
  document.body.classList.toggle("rtl", isRTL);
  document.body.classList.toggle("ltr", !isRTL);

  // Keep the header layout left-to-right; the rest of the page follows the language.
  const header = document.querySelector("header.site-header");
  if (header) { header.classList.add("ltr"); header.setAttribute("dir", "ltr"); }

  const navbar = document.querySelector(".nav");
  if (navbar) navbar.classList.toggle("arabic-font-size", isRTL);
}

// Automatically load the saved language on page load
document.addEventListener("DOMContentLoaded", () => {
  const savedLanguage = localStorage.getItem("language") || "en"; // Default to English
  changeLanguage(savedLanguage);
});
